// Card menu-imagens-sem-buraco: the menu's tiny blurred previews. Each picture the menu waits on (the popup's two
// escolha arts in both orientations, the chosen hero's portrait, the profile's face and its 3 photos) gets a ~24 px copy
// inlined as a data URI in src/client/ui/menu-previas.ts; the page shows it (blurred) until the real file is decoded,
// so a slow 4G never shows a hole (preload/menu-art-preload.ts).
// Usage: node scripts/menu-previas.mjs [--check]   (--check: exit 1 when the generated file is stale)
import {readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import sharp from 'sharp';

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
export const OUT=path.join(ROOT,'src','client','ui','menu-previas.ts');
/** The long side of a preview, in px: big enough to read the colours and the shapes, ~300 bytes. */
export const LADO=24;
// Kept in step with ui/escolha-popup.ts ESCOLHA_HEROIS and ui/insta.ts INSTA_PERFIS (tests/tools/menu-previas.test.ts).
export const HEROIS=['aposentado','clt-cansado','gato-nada-pra-comer','maromba','vendedor-praia','viciado-em-bet'];

/** The site paths that get a preview, in a fixed order. */
export function urls(herois=HEROIS){
  const out=[];
  for(const id of herois){
    for(const k of ['amigos','sozinho','amigos-deitado','sozinho-deitado'])out.push(`/art/menu/escolha/${id}-${k}.webp`);
    out.push(`/art/portraits/${id}-thumb.webp`,`/art/lite/menu/insta/perfil-${id}.webp`);
    for(const i of [1,2,3])out.push(`/art/lite/menu/insta/grade-${id}-${i}.webp`);
  }
  return out;
}

export async function previa(file){
  const buf=await sharp(file).resize(LADO,LADO,{fit:'inside'}).webp({quality:30,alphaQuality:30,effort:6,smartSubsample:true}).toBuffer();
  return `data:image/webp;base64,${buf.toString('base64')}`;
}

export async function gerar(){
  const linhas=[];
  for(const url of urls())linhas.push(`  '${url}':'${await previa(path.join(ROOT,'public',url))}',`);
  return `// Generated by scripts/menu-previas.mjs from the files in public/: do not edit (run it again after new menu art).\n`+
    `/** The menu's blurred previews (${LADO} px), by the site path of the real file. */\n`+
    `export const PREVIAS:Readonly<Record<string,string>>={\n${linhas.join('\n')}\n};\n`;
}

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  const novo=await gerar();
  if(process.argv.includes('--check')){
    const atual=await readFile(OUT,'utf8').catch(()=>'');
    if(atual!==novo){console.error('menu-previas.ts is stale: node scripts/menu-previas.mjs');process.exit(1);}
    console.log('menu-previas.ts fresh');
  }else{
    await writeFile(OUT,novo);
    console.log(`${OUT}: ${urls().length} previews, ${Buffer.byteLength(novo)} bytes`);
  }
}
